import { path } from '@servicenow/sdk-build-core'
import { createTestContext, getMergedRecordUpdates, loadTestFile } from './test-utils'
import { gunzipSync } from 'zlib'

describe('Inline Scripts Bi-Directionality Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Inline Scripts - Fluent to XML', () => {
        test('Flow with basic inline scripts', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'inline-script-basic.now.ts',
                'inline-scripts'
            )

            // Verify action instances were created
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find a log action with inline script
            const logWithInlineScript = actionInstances.find(
                (action: any) =>
                    action.ui_id === 'log_simple_string' || action.comment === 'Log with simple string inline script'
            )
            expect(logWithInlineScript).toBeDefined()

            // Verify inline script is in values field
            if (logWithInlineScript) {
                const inputs = JSON.parse(
                    gunzipSync(Buffer.from(logWithInlineScript.values, 'base64')).toString('utf8')
                )
                expect(inputs).toBeDefined()
                expect(Array.isArray(inputs)).toBe(true)

                // Check for script structure
                const logMessageInput = inputs.find((input: any) => input.name === 'log_message')
                expect(logMessageInput).toBeDefined()
                expect(logMessageInput.scriptActive).toBe(true)
                expect(logMessageInput.script).toBeDefined()
                expect(logMessageInput.script.log_message).toBeDefined()
                expect(logMessageInput.script.log_message.script).toContain("return 'Hello from inline script!'")
            }
        })

        test('Flow with inline scripts accessing fd_data', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'inline-script-basic.now.ts',
                'inline-scripts'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find action with inline script accessing trigger data
            const logTriggerData = actionInstances.find(
                (action: any) => action.comment === 'Log trigger data from inline script'
            )
            expect(logTriggerData).toBeDefined()

            if (logTriggerData) {
                const inputs = JSON.parse(gunzipSync(Buffer.from(logTriggerData.values, 'base64')).toString('utf8'))

                const logMessageInput = inputs.find((input: any) => input.name === 'log_message')
                expect(logMessageInput.scriptActive).toBe(true)
                expect(logMessageInput.script.log_message.script).toContain('fd_data.trigger.current.number')
            }
        })

        test.skip('Subflow with inline scripts', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'inline-script-subflow.now.ts',
                'inline-scripts'
            )

            // Verify subflow was created
            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']

            // Find the test subflow
            const subflow = flows.find(
                (flow: any) => flow.name === 'Test - Process User Access - Inline Script Example'
            )
            expect(subflow).toBeDefined()

            // Verify subflow has actions with inline scripts
            const actionInstances = merged['sys_hub_action_instance_v2']
            const subflowActions = actionInstances.filter((action: any) => action.flow === subflow?.sys_id)
            expect(subflowActions.length).toBeGreaterThan(0)

            // Check for inline script in welcome email
            const welcomeEmail = subflowActions.find(
                (action: any) => action.comment === 'Send personalized welcome email'
            )
            expect(welcomeEmail).toBeDefined()

            if (welcomeEmail) {
                const inputs = JSON.parse(gunzipSync(Buffer.from(welcomeEmail.values, 'base64')).toString('utf8'))
                const bodyInput = inputs.find((input: any) => input.name === 'ah_body')
                expect(bodyInput).toBeDefined()
                expect(bodyInput.scriptActive).toBe(true)
                expect(bodyInput.script.ah_body.script).toContain('fd_data.sub_flow.inputs')
            }
        })

        test('Flow with inline scripts in ForEach', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'inline-script-foreach.now.ts',
                'inline-scripts'
            )

            // Verify ForEach logic instance
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            const forEachInstance = flowLogicInstances.find(
                (logic: any) => logic.logic_definition === '098e1dc5c3e232002841b63b12d3ae33'
            )
            expect(forEachInstance).toBeDefined()

            // Check for action inside ForEach with inline script
            const actionInstances = merged['sys_hub_action_instance_v2']
            const watcherLog = actionInstances.find(
                (action: any) => action.comment === 'Log watcher notification with inline script'
            )
            expect(watcherLog).toBeDefined()

            if (watcherLog) {
                const inputs = JSON.parse(gunzipSync(Buffer.from(watcherLog.values, 'base64')).toString('utf8'))

                const logMessageInput = inputs.find((input: any) => input.name === 'log_message')
                expect(logMessageInput.scriptActive).toBe(true)
                expect(logMessageInput.script.log_message.script).toContain('fd_data._5__for_each')
            }
        })

        test('Inline script with action output reference', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'inline-script-action-outputs.now.ts',
                'inline-scripts'
            )

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find summary log with action output references
            const summaryLog = actionInstances.find(
                (action: any) => action.comment === 'Final summary with all context'
            )
            expect(summaryLog).toBeDefined()

            if (summaryLog) {
                const inputs = JSON.parse(gunzipSync(Buffer.from(summaryLog.values, 'base64')).toString('utf8'))

                const logMessageInput = inputs.find((input: any) => input.name === 'log_message')
                expect(logMessageInput.scriptActive).toBe(true)
                expect(logMessageInput.script.log_message.script).toContain('fd_data.steps.')
                expect(logMessageInput.script.log_message.script).toContain('.result.record')
                expect(logMessageInput.script.log_message.script).toContain('JSON.stringify')
            }
        })
    })

    describe('Inline Scripts - XML to Fluent', () => {
        test('XML with inline scripts transforms to wfa.inlineScript()', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_baa1cbdea5b97210f8775dd4faa86460.xml', 'inline-scripts/xmls')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_baa1cbdea5b97210f8775dd4faa86460.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('sys_hub_flow_baa1cbdea5b97210f8775dd4faa86460.now.ts')

            const content = changedFiles[0].getContent()

            // Verify wfa.inlineScript() is generated
            expect(content).toContain('wfa.inlineScript(')

            // Verify no external .js files created (only .now.ts file)
            expect(changedFiles.length).toBe(1)
        })

        test('XML with inline scripts in ForEach transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_baa1cbdea5b97210f8775dd4faa86460.xml', 'inline-scripts/xmls')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_baa1cbdea5b97210f8775dd4faa86460.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify ForEach exists
            expect(content).toContain('wfa.flowLogic.forEach(')

            // Verify data pill was converted
            expect(content).toContain('params.trigger.current.additional_assignee_list')

            // Verify inline script inside ForEach
            expect(content).toContain('wfa.inlineScript(')
        })

        test('XML with inline scripts accessing fd_data transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_baa1cbdea5b97210f8775dd4faa86460.xml', 'inline-scripts/xmls')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_baa1cbdea5b97210f8775dd4faa86460.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify fd_data references are preserved in inline scripts
            expect(content).toContain('fd_data._1__for_each')
            expect(content).toContain('wfa.inlineScript(')
        })

        test('Inline scripts have correct structure in generated code', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_baa1cbdea5b97210f8775dd4faa86460.xml', 'inline-scripts/xmls')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_baa1cbdea5b97210f8775dd4faa86460.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify log action exists
            expect(content).toContain('action.core.log')

            // Verify inline script is used for log_message
            expect(content).toContain('log_message: wfa.inlineScript(')

            // Verify create record action exists
            expect(content).toContain('action.core.createRecord')
        })
    })

    describe('Inline Scripts - Round Trip', () => {
        test('Fluent → XML preserves inline script content', async () => {
            const merged = await getMergedRecordUpdates(
                ctx.createProject(),
                'inline-script-basic.now.ts',
                'inline-scripts'
            )

            expect(merged['sys_hub_flow']).toBeDefined()
            const flows = merged['sys_hub_flow']
            const testFlow = flows.find((flow: any) => flow.name === 'Test - Inline Script Example Basic')
            expect(testFlow).toBeDefined()

            // Verify action instances with inline scripts exist
            const actionInstances = merged['sys_hub_action_instance_v2']
            const actionsWithScripts = actionInstances.filter((action: any) => {
                if (!action.values) {
                    return false
                }
                const inputs = JSON.parse(gunzipSync(Buffer.from(action.values, 'base64')).toString('utf8'))
                return Array.isArray(inputs) && inputs.some((input: any) => input.scriptActive === true)
            })
            expect(actionsWithScripts.length).toBeGreaterThan(0)
        })
    })
})
